ee:variables.ee:set-variable:
%dw 2.0
output application/java
var nowSeconds = (now() as Number {unit: "seconds"})
---
{
  jti: uuid(),
  aud: p("wbd.jwt.audience"),
  sub: vars.activationRequest.partner_user_id,
  iss: p("wbd.jwt.issuer"),
  iat: nowSeconds,
  exp: nowSeconds + (p("wbd.jwt.ttl") as Number),
  provider: p("wbd.jwt.provider"),
  address: {
    country: p("wbd.jwt.country")
  },
  products: [
    {
      code: vars.activationRequest.code,
      starts: vars.activationRequest.starts,
      sub_id: vars.activationRequest.sub_id
    }
  ]
}

java:invoke-static.java:args:
#[{
   claimsJson: write(vars.jwtClaims, "application/json"),
   privateKeyPem: p("wbd.jwt.privateKey"),
   keyId: p("wbd.jwt.keyId")
}]
